#!/usr/bin/env python3
"""Create a local-only literal transcript review; never prints private contents."""
import argparse,base64,html,json,subprocess,sys,uuid
from pathlib import Path
sys.path.insert(0,str(Path(__file__).parent));import experiment as e
PAGE='''<!doctype html><meta charset="utf-8"><title>Sliplet · Reading check</title>
<style>body{font:16px system-ui;margin:30px;background:#f4f4f6;color:#222}button,select{font:inherit;padding:10px;border-radius:12px;border:1px solid #bbb;background:white}header{max-width:1000px;margin:auto}main{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:20px}#photo{position:sticky;top:12px;align-self:start;max-height:85vh;overflow:auto;background:#ddd}canvas{width:100%;display:block;cursor:crosshair}textarea{width:95%;font:14px monospace;padding:8px;min-height:38px}article{background:white;border-radius:10px;padding:8px;margin:6px 0}label{display:block;margin:12px 0}.selected{outline:2px solid #4785ee}small{color:#555}input{accent-color:#2765ce}</style>
<header><h1>Check what is actually printed</h1><p>This stays on your Mac. Choose one receipt to start. Compare every text row with the photo, correcting literal wording only. Keep product codes, punctuation and printed amounts. Do not calculate missing values or rewrite the receipt into a cleaner format.</p><p>Click a text row to highlight its source. For missing text, choose Add row, then draw its area on the photo. Choose Mark reading region and draw a useful area for a focused reread. Text verification and region verification are separate.</p><select id="picker"></select> <button onclick="add()">Add row</button> <button onclick="regionMode=true">Mark reading region</button> <button onclick="download()">Export checked work</button><p id="status"></p></header>
<main><div id="photo"><canvas id="canvas"></canvas></div><div><label><input id="verified" type="checkbox" onchange="current().humanVerified=this.checked"> I compared every row and its location against the photo, including missing text.</label><label><input id="rv" type="checkbox" onchange="current().regionVerified=this.checked"> I checked that my reading region contains the intended text.</label><label>Printed currency <select id="currency" onchange="current().currencyEvidence=this.value"><option value="unreviewed">Not checked</option><option value="CAD">CAD or CA$ explicitly printed</option><option value="not_printed">No currency identifier printed ($ alone does not identify currency)</option><option value="other_or_unclear">Other or unclear</option></select></label><div id="rows"></div></div></main>
<script>const payload=PAYLOAD;let index=0,selected=-1,regionMode=false,start=null;const images=[];const cv=document.getElementById('canvas'),ctx=cv.getContext('2d');function current(){return payload.receipts[index]}function draw(){let im=images[index];if(!im||!im.complete)return;cv.width=im.naturalWidth;cv.height=im.naturalHeight;ctx.drawImage(im,0,0);const boxes=[];if(selected>=0&&current().observations[selected]?.boundingBox)boxes.push([current().observations[selected].boundingBox,'#2675ff']);if(current().region)boxes.push([current().region,'#e77b15']);for(let [b,c]of boxes){ctx.strokeStyle=c;ctx.lineWidth=Math.max(3,cv.width/180);ctx.strokeRect(b.x*cv.width,(1-b.y-b.height)*cv.height,b.width*cv.width,b.height*cv.height)}}function render(){selected=-1;document.getElementById('verified').checked=current().humanVerified;document.getElementById('rv').checked=current().regionVerified;document.getElementById('currency').value=current().currencyEvidence;const rows=document.getElementById('rows');rows.replaceChildren();current().observations.forEach((r,i)=>{let a=document.createElement('article'),t=document.createElement('textarea'),b=document.createElement('button');t.value=r.text;t.onfocus=()=>{selected=i;draw()};t.oninput=()=>{r.text=t.value;current().humanVerified=false;document.getElementById('verified').checked=false};b.textContent='Remove row';b.onclick=()=>{current().observations.splice(i,1);current().humanVerified=false;render()};a.append(t,b);rows.append(a)});draw()}function add(){current().observations.push({id:crypto.randomUUID(),text:'',engineConfidence:0});current().humanVerified=false;render();selected=current().observations.length-1;document.getElementById('status').textContent='Draw the new row’s source area on the photo, then enter its literal text.'}function point(ev){let r=cv.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(ev.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,1-(ev.clientY-r.top)/r.height))}}cv.onpointerdown=ev=>{start=point(ev);cv.setPointerCapture(ev.pointerId)};cv.onpointerup=ev=>{if(!start)return;let end=point(ev),b={x:Math.min(start.x,end.x),y:Math.min(start.y,end.y),width:Math.abs(end.x-start.x),height:Math.abs(end.y-start.y)};start=null;if(b.width<.002||b.height<.002)return;if(regionMode){current().region=b;current().regionVerified=false;document.getElementById('rv').checked=false;regionMode=false}else if(selected>=0){current().observations[selected].boundingBox=b;current().humanVerified=false;document.getElementById('verified').checked=false}draw()};function download(){let out={schemaVersion:1,nonce:payload.nonce,receipts:payload.receipts.map(({image,...r})=>r)};let blob=new Blob([JSON.stringify(out,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='sliplet-p402-checked.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}payload.receipts.forEach((r,i)=>{let op=document.createElement('option');op.value=i;op.textContent='Receipt '+(i+1);document.getElementById('picker').append(op);let im=new Image();im.onload=draw;im.src=r.image;images.push(im)});document.getElementById('picker').onchange=ev=>{index=Number(ev.target.value);render()};render();</script>'''
def main():
    p=argparse.ArgumentParser();p.add_argument('--output',required=True);a=p.parse_args();out=e.lab.private(a.output)
    if out.exists():raise ValueError('new_output_required')
    out.mkdir(parents=True,mode=0o700);manifest=e.read(e.BASE/'manifest.json');receipts=[]
    for i,g in enumerate(manifest['groups']):
        original=g['images'][0];target=out/f'preview-{i}.png'
        subprocess.run(['sips','-s','format','png',original['path'],'--out',str(target)],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,check=True)
        target.chmod(0o600);capture=e.BASE/'captures'/f'capture-{i}-1.json'
        receipts.append({'slot':i,'sourceHash':original['sha256'],'captureHash':e.digest(capture),'image':'data:image/png;base64,'+base64.b64encode(target.read_bytes()).decode(),'observations':e.read(capture)['observations'],'humanVerified':False,'regionVerified':False,'region':None,'currencyEvidence':'unreviewed'})
    payload={'nonce':str(uuid.uuid4()),'receipts':receipts}
    e.write(out/'identity.json',{'nonce':payload['nonce'],'receipts':[{k:r[k] for k in ('slot','sourceHash','captureHash')} for r in receipts]})
    page=out/'review.html';page.write_text(PAGE.replace('PAYLOAD',json.dumps(payload).replace('<','\\u003c')));page.chmod(0o600)
    print('Local review page created for five receipts; all confirmations start unchecked.')
if __name__=='__main__':main()
